/**
 * @file listWindow.ts
 * @input Fixed or per-item CSS-pixel pitch, scroll geometry and canonical row keys
 * @output Half-open ranges, row and gap segments, and first-visible-key reconciliation
 * @position The one private long-list windowing module in Core
 */

export function isPositiveFinite(value) {
  return Number.isFinite(value) && value > 0;
}

/** Returns null when the inputs cannot form a finite window. */
export function calculateListWindow(options) {
  const {
    rowCount,
    rowHeight,
    viewportHeight,
    scrollTop,
    startOffset,
    isMeasured,
    focusIndex
  } = options;
  const totalHeight = rowCount * rowHeight;
  if (!Number.isSafeInteger(rowCount) || rowCount < 0 || !isPositiveFinite(rowHeight) || !isPositiveFinite(viewportHeight) || !Number.isFinite(totalHeight) || !Number.isFinite(startOffset + totalHeight) || !Number.isFinite(viewportHeight / rowHeight) || !Number.isFinite(scrollTop) || options.scrollHeight !== undefined && (!Number.isFinite(options.scrollHeight) || options.scrollHeight < 0) || !Number.isFinite(startOffset) || startOffset < 0) {
    return null;
  }
  if (rowCount === 0) {
    return {
      segments: [],
      start: 0,
      end: 0,
      firstVisibleIndex: 0,
      offset: 0,
      totalHeight: 0
    };
  }

  // Clamp against the full body extent, not mounted DOM or window-local indices.
  const contentHeight = Math.max(startOffset + totalHeight, options.scrollHeight ?? 0);
  const maximumScroll = Math.max(0, contentHeight - viewportHeight);
  const clampedScroll = Math.min(maximumScroll, Math.max(0, scrollTop));
  const listTop = clampedScroll - startOffset;
  const bodyTop = Math.min(totalHeight, Math.max(0, listTop));
  const bodyBottom = Math.min(totalHeight, Math.max(0, clampedScroll + viewportHeight - startOffset));
  const firstVisibleIndex = isMeasured ? Math.min(rowCount - 1, Math.floor(bodyTop / rowHeight)) : 0;
  // Above the first row, the offset is the negative distance to it, so an
  // anchor round-trips a scroll position inside the leading content.
  const offset = !isMeasured ? 0 : listTop < 0 ? listTop : bodyTop - firstVisibleIndex * rowHeight;
  const start = isMeasured ? Math.max(0, firstVisibleIndex - 4) : 0;
  const end = isMeasured ? Math.min(rowCount, Math.max(firstVisibleIndex, Math.ceil(bodyBottom / rowHeight)) + 4) : Math.min(rowCount, Math.ceil(viewportHeight / rowHeight) + 4);
  return {
    segments: createListWindowSegments(rowCount, rowHeight, start, end, focusIndex),
    start,
    end,
    firstVisibleIndex,
    offset,
    totalHeight
  };
}

/** Mounted rows and gaps for a range, plus one retained row outside it. */
export function createListWindowSegments(rowCount, rowHeight, start, end, focusIndex) {
  if (rowCount === 0) {
    return [];
  }
  const intervals = [{
    start,
    end
  }];
  if (focusIndex !== undefined && Number.isInteger(focusIndex) && focusIndex >= 0 && focusIndex < rowCount && (focusIndex < start || focusIndex >= end)) {
    intervals.push({
      start: focusIndex,
      end: focusIndex + 1
    });
    intervals.sort((a, b) => a.start - b.start);
  }
  const merged = [];
  for (const interval of intervals) {
    const previous = merged[merged.length - 1];
    if (previous && interval.start <= previous.end) {
      previous.end = Math.max(previous.end, interval.end);
    } else if (interval.end > interval.start) {
      merged.push({
        ...interval
      });
    }
  }
  const segments = [];
  let cursor = 0;
  for (const interval of merged) {
    if (interval.start > cursor) {
      segments.push({
        type: 'gap',
        start: cursor,
        end: interval.start,
        height: (interval.start - cursor) * rowHeight
      });
    }
    segments.push({
      type: 'rows',
      ...interval
    });
    cursor = interval.end;
  }
  if (cursor < rowCount) {
    segments.push({
      type: 'gap',
      start: cursor,
      end: rowCount,
      height: (rowCount - cursor) * rowHeight
    });
  }
  return segments;
}
/**
 * The first index in `[0, limit)` whose offset is at least `value`, or above
 * it when `isStrict` is set.
 */
function lowerBound(offsets, value, limit, isStrict = false) {
  let low = 0;
  let high = limit;
  while (low < high) {
    const middle = low + high >> 1;
    if (isStrict ? offsets[middle] <= value : offsets[middle] < value) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }
  return low;
}

/**
 * The half-open item range for items of varying size. Before measurement it
 * holds the items that start inside the viewport, plus overscan after them.
 */
export function calculateVariableListRange({
  offsets,
  viewportSize,
  scrollOffset,
  isMeasured,
  overscan
}) {
  const count = Math.max(0, offsets.length - 1);
  if (count === 0) {
    return {
      start: 0,
      end: 0,
      firstVisibleIndex: 0,
      offset: 0
    };
  }
  if (!isMeasured) {
    return {
      start: 0,
      end: Math.min(count, lowerBound(offsets, viewportSize, count) + overscan),
      firstVisibleIndex: 0,
      offset: 0
    };
  }
  const total = offsets[count];
  const visibleSize = Math.max(0, viewportSize);
  const scroll = Math.min(Math.max(0, total - visibleSize), Math.max(0, scrollOffset));
  // The last item that starts at or before the scroll offset.
  const first = Math.max(0, Math.min(count - 1, lowerBound(offsets, scroll, count, true) - 1));
  const last = Math.max(first + 1, lowerBound(offsets, scroll + visibleSize, count));
  return {
    start: Math.max(0, first - overscan),
    end: Math.min(count, last + overscan),
    firstVisibleIndex: first,
    offset: scroll - offsets[first]
  };
}
export function reconcileListAnchor(options) {
  const {
    previousKeys,
    keys,
    firstVisibleIndex,
    offset,
    rowHeight,
    viewportHeight,
    startOffset
  } = options;
  const indices = options.keyIndices ?? new Map(keys.map((key, index) => [key, index]));
  let index = indices.get(previousKeys[firstVisibleIndex]);
  if (index === undefined) {
    for (let i = firstVisibleIndex + 1; i < previousKeys.length; i++) {
      index = indices.get(previousKeys[i]);
      if (index !== undefined) {
        break;
      }
    }
  }
  if (index === undefined) {
    for (let i = Math.min(firstVisibleIndex - 1, previousKeys.length - 1); i >= 0; i--) {
      index = indices.get(previousKeys[i]);
      if (index !== undefined) {
        break;
      }
    }
  }
  const {
    offsets
  } = options;
  const maximumScroll = Math.max(0, startOffset + (offsets ? offsets[keys.length] ?? 0 : keys.length * rowHeight) + (options.trailingContentHeight ?? 0) - viewportHeight);
  if (offsets) {
    const itemStart = offsets[index ?? 0] ?? 0;
    const itemSize = index === undefined ? 0 : offsets[index + 1] - itemStart;
    const fraction = Math.min(1, Math.max(0, offset));
    return Math.max(0, Math.min(maximumScroll, startOffset + itemStart + fraction * itemSize));
  }
  // With no surviving key, a position inside the leading content stays where
  // it is, and a position inside the rows moves to the first row.
  const fraction = index === undefined ? Math.min(0, Math.max(-startOffset, offset)) : Math.min(Math.max(-startOffset, offset), rowHeight);
  return Math.min(maximumScroll, startOffset + (index ?? 0) * rowHeight + fraction);
}